AS x("lessonId" text,"sourcePage" integer,"lessonTitle" text,activity_order integer,activity_type text,title text,section text,prompt text,content jsonb,answer jsonb);
DO $safe$
DECLARE eligible int; protected int; inserted int;
BEGIN
 IF (SELECT count(*) FROM pg_temp.bh_g1_9_letter_context_20261030)<>9 OR
 (SELECT count(DISTINCT lesson_id) FROM pg_temp.bh_g1_9_letter_context_20261030)<>9 OR
 EXISTS(SELECT 1 FROM pg_temp.bh_g1_9_letter_context_20261030 WHERE
 length(content->>'originalReference')<180 OR content ? 'answer' OR content ? 'correct' OR
 NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(content->'options') v WHERE v=answer->>'correct'))
 THEN RAISE EXCEPTION 'Invalid Grade1 letter-position exercise package'; END IF;
 SELECT count(*) INTO eligible FROM public.lessons l JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
 JOIN public.curricula cu ON cu.id=g.curriculum_id JOIN public.countries co ON co.id=cu.country_id
 JOIN pg_temp.bh_g1_9_letter_context_20261030 t ON t.lesson_id=l.id AND t.source_page=l.source_page_start AND t.lesson_title=l.title
 WHERE co.code='BH' AND g.grade_number=1 AND l.status='published'
 AND (SELECT count(*) FROM public.lesson_activities a WHERE a.lesson_id=l.id AND a.is_published)=5
 AND (SELECT max(activity_order) FROM public.lesson_activities a WHERE a.lesson_id=l.id)=206
 AND NOT EXISTS(SELECT 1 FROM public.student_lesson_progress p WHERE p.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.lesson_activity_attempts at JOIN public.lesson_activities a ON a.id=at.activity_id WHERE a.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.question_attempts at JOIN public.questions q ON q.id=at.question_id WHERE q.lesson_id=l.id);
 IF eligible<>9 THEN RAISE EXCEPTION 'Scope drift or protected learner history: % Grade1 letters instead of 9',eligible; END IF;
 IF EXISTS(SELECT 1 FROM public.lesson_activities WHERE content->>'origin'='DADYOOM_BH_G1_9_LETTER_SOUND_CONTEXT_20261030') THEN
 RAISE EXCEPTION 'Prevent double insertion of Grade1 letter-position activities'; END IF;
 INSERT INTO public.lesson_activities
 (lesson_id,title,activity_type,instructions,content,activity_order,points,is_published,section,prompt,answer,is_required)
 SELECT l.id,t.title,t.activity_type,'اقرأ الكلمات وتعرّف موضع الحرف حسب السؤال. بطاقة ضاديوم إثرائية أصلية.',
 t.content,t.activity_order,5,true,t.section,t.prompt,t.answer,false
 FROM public.lessons l JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
 JOIN public.curricula cu ON cu.id=g.curriculum_id JOIN public.countries co ON co.id=cu.country_id
 JOIN pg_temp.bh_g1_9_letter_context_20261030 t ON t.lesson_id=l.id AND t.source_page=l.source_page_start AND t.lesson_title=l.title
 WHERE co.code='BH' AND g.grade_number=1 AND l.status='published'
 AND NOT EXISTS(SELECT 1 FROM public.student_lesson_progress p WHERE p.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.lesson_activity_attempts at JOIN public.lesson_activities a ON a.id=at.activity_id WHERE a.lesson_id=l.id)
 AND NOT EXISTS(SELECT 1 FROM public.question_attempts at JOIN public.questions q ON q.id=at.question_id WHERE q.lesson_id=l.id);
 GET DIAGNOSTICS inserted=ROW_COUNT;
 IF inserted<>9 THEN RAISE EXCEPTION 'Atomic rollback inserted % not 9',inserted; END IF;
 RAISE NOTICE 'Original Grade1 letter-position activity count=%',inserted;
END $safe$;
COMMIT;